"""Production SCD consumers with generated bytes; no original game content."""
from pathlib import Path
import hashlib, importlib.util, os, shutil, struct, subprocess, sys, tempfile
from unittest.mock import patch
ROOT=Path(__file__).resolve().parents[2]
def fixture(aux=0,empty=False):
 data=bytearray(256);data[:8]=b'SEDBSSCF';struct.pack_into('<I',data,0x3c,0x60);struct.pack_into('<I',data,0x60,0x80)
 struct.pack_into('<8i',data,0x80,0,2,44100,6,0,0,0,aux)
 data[0xa0:0xa3]=bytes((2,32,0))
 ogg=b'OggS'+bytes(22)+bytes((1,0))
 struct.pack_into('<II',data,0xb0,0,0 if empty else len(ogg))
 if not empty:data[0xc0:0xc0+len(ogg)]=ogg
 return bytes(data)
def main():
 s=(ROOT/'port/decompui/hd_import.inc').read_text(encoding='utf-8')
 consumer=s[s.index('static uint32_t U32('):s.index('\n/* ---- movie subtitles')]
 prefix='#include <vector>\n#include <cstdint>\n#include <cstring>\n#include <fstream>\n#include <iterator>\n'
 test='''int main(int argc,char**argv){if(argc!=3)return 3;std::ifstream in(argv[1],std::ios::binary);std::vector<unsigned char> data((std::istreambuf_iterator<char>(in)),{}),out={42};if(std::string(argv[1]).find("empty-ogg")!=std::string::npos){out.clear();out.shrink_to_fit();}const auto before=out;uint64_t a=99,b=99;bool ok=ScdToOgg(data,out,a,b);bool expected=argv[2][0]=='1';return ok!=expected || (!ok && (out!=before || a!=99 || b!=99)) ? 4:0;}'''
 spec=importlib.util.spec_from_file_location('scd',ROOT/'port/tools/khhd_scd.py');scd=importlib.util.module_from_spec(spec);spec.loader.exec_module(scd)
 def changed(at,value):
  data=bytearray(fixture());struct.pack_into('<I',data,at,value);return bytes(data)
 valid_aux=bytearray(fixture());valid_aux[0xa8:]=valid_aux[0xa0:-8];valid_aux[0xa0:0xa8]=b'AUX '+struct.pack('<I',8);struct.pack_into('<I',valid_aux,0x9c,1)
 encrypted=bytearray(fixture());encrypted[0xa2]=0x5a
 for i in range(28):encrypted[0xc0+i]^=0x5a
 cases=[('valid-aux',bytes(valid_aux),True),('valid-xor-vorbis',bytes(encrypted),True),('bad-table',changed(0x3c,0xffffffff),False),('bad-entry',changed(0x60,0xffffffff),False),('negative-size',changed(0x80,0xffffffff),False),('negative-aux',changed(0x9c,0xffffffff),False),('bad-header-size',fixture()[:0xa1]+b'\x01'+fixture()[0xa2:],False),('bad-seek',changed(0xb0,0xffffffff),False),('bad-vorbis',changed(0xb4,0xffffffff),False),('valid',fixture(),True),('empty-ogg',fixture(empty=True),False),('zero-chunk',fixture(aux=2),False),('huge-aux',fixture(aux=2147483647),False),('truncated',fixture()[:100],False)]
 with tempfile.TemporaryDirectory(prefix='khcom-scd-') as folder:
  temp=Path(folder);unit=temp/'scd.cpp';unit.write_text(prefix+consumer+test,encoding='utf-8')
  compiler=os.environ.get('CXX') or shutil.which('clang++') or shutil.which('g++')
  if not compiler:compiler=str(next((ROOT.parent.parent/'toolchain').glob('llvm-mingw-*/bin/clang++.exe')))
  exe=temp/('test.exe' if os.name=='nt' else 'test');subprocess.run([compiler,'-std=c++17','-static',str(unit),'-o',str(exe)],check=True)
  failures=[]
  for name,data,valid in cases:
   file=temp/(name+'.scd');file.write_bytes(data)
   for backend,command in [('cpp',[str(exe),str(file),str(int(valid))]),('python',[sys.executable,'-c','import sys;sys.path.insert(0,sys.argv[1]);import khhd_scd;khhd_scd.convert(open(sys.argv[2],"rb").read())',str(ROOT/'port/tools'),str(file)])]:
    try:
     run=subprocess.run(command,capture_output=True,text=True,timeout=2)
     good=run.returncode==0 if backend=='cpp' or valid else run.returncode!=0
     print(name,backend,run.returncode)
    except subprocess.TimeoutExpired:good=False;print(name,backend,'TIMEOUT')
    if not good:failures.append((name,backend))
  assert not failures,failures
  # Full native transaction -> real subprocess producer -> package -> SCD.
  spec=importlib.util.spec_from_file_location('launcher',ROOT/'port/linux/launcher/rekhcom_launcher.py');launcher=importlib.util.module_from_spec(spec);spec.loader.exec_module(launcher)
  source=temp/'owned-source';movies=source/'STEAM/dt/KHCReSource/BIN/movie';movies.mkdir(parents=True)
  plain=b'\0\0\0\x08moov\0\0\0\x08mdat';key=bytes.fromhex('3f1ec193264258b8aa9d5375bf629a97')
  for name in ('ROP','RSE','RRE','zz_event_151','zz_event_621','zz_event_631'):(movies/(name+'.mp4')).write_bytes(bytes(b^key[i%16] for i,b in enumerate(plain)))
  image=source/'Image/dt';image.mkdir(parents=True)
  (image/'Recom.hed').write_bytes(struct.pack('<16sqii',hashlib.md5(b'STREAM/0001/Title.win32.scd').digest(),0,272,256))
  game=temp/'game';(game/'hd/music').mkdir(parents=True);old=game/'hd/music/old.ogg';old.write_bytes(b'OggS original');save=game/'kh_com.sav';save.write_bytes(b'owned-save')
  def package(data):(image/'Recom.pkg').write_bytes(struct.pack('<iiii',len(data),0,-2,0)+data)
  with patch.dict(os.environ,{'PATH':''}):
   package(fixture(aux=2147483647))
   try:launcher.transaction(game,source,launcher.source_producer())
   except subprocess.CalledProcessError:pass
   else:raise AssertionError('Native producer accepted zero-progress SCD')
   assert old.read_bytes()==b'OggS original' and save.read_bytes()==b'owned-save'
   assert not list(game.glob('.hd-import-*')) and not (game/'.rekhcom-hd-import.lock').exists()
   package(fixture());backup=launcher.transaction(game,source,launcher.source_producer())
   assert (game/'hd/music/Title.ogg').read_bytes().startswith(b'OggS')
   assert old.read_bytes()==b'OggS original' and save.read_bytes()==b'owned-save' and backup.is_dir()
  print('PASS native transaction + real producer subprocess + package/SCD: rejection preserves HD/save, valid control commits')
if __name__=='__main__':main()

